prompt.template:
Define the quality metrics that all activities must meet before commit:

1. Create .activity-quality-gates.json:
```json
{
  "quality_gates": {
    "test_coverage": {
      "minimum": 0.80,
      "description": "Must have at least 80% test coverage",
      "check_command": "npm test -- --coverage --coverageThreshold={...}"
    },
    "no_critical_issues": {
      "maximum_critical": 0,
      "description": "No HIGH/CRITICAL Metabob issues allowed",
      "check_command": "metabob-cli get-priority-issues --severity CRITICAL"
    },
    "no_dead_code": {
      "maximum_dead_code_lines": 0,
      "description": "No unused functions or dead code",
      "check_command": "metabob-cli search-issues --pattern 'dead.*code|unused.*function'"
    },
    "memory_improvement": {
      "minimum_improvement": 0.20,
      "description": "Memory fixes must show at least 20% improvement",
      "check_command": "npm test -- test-memory-leak.ts"
    },
    "no_manual_intervention": {
      "requires_user_input": false,
      "description": "Activity must not require user input to validate fixes",
      "check_command": "grep -r 'TODO.*user' src/"
    },
    "all_tests_pass": {
      "test_pass_rate": 1.0,
      "description": "All tests must pass",
      "check_command": "npm test"
    },
    "no_breaking_changes": {
      "semver_violations": 0,
      "description": "No breaking API changes",
      "check_command": "npm run check:semver"
    }
  },
  "activity_gates": {
    "fix": {
      "required_gates": ["all_tests_pass", "no_critical_issues"],
      "nice_to_have": ["test_coverage", "no_dead_code"]
    },
    "feature": {
      "required_gates": ["all_tests_pass", "test_coverage", "no_critical_issues"],
      "nice_to_have": ["no_dead_code"]
    },
    "bugfix": {
      "required_gates": ["all_tests_pass", "no_critical_issues", "memory_improvement"],
      "nice_to_have": ["test_coverage"]
    }
  }
}
```

2. Document each metric:
- Why it matters
- How to measure it
- How to fix violations
- Exceptions (if any)

3. Save to git repo:
```bash
git add .activity-quality-gates.json
git commit -m 'docs: Define activity quality gates to prevent bad code commits'
```

Create clear failure conditions for activities:

1. Create .activity-failure-conditions.json:
```json
{
  "automatic_failures": [
    {
      "condition": "requires_user_input",
      "description": "Activity needs user to verify or input data",
      "indicators": ["awaits user response", "manual review needed", "please provide"],
      "action": "FAIL activity immediately",
      "reason": "Indicates activity is incomplete or can't be automated"
    },
    {
      "condition": "test_coverage_drop",
      "description": "Test coverage decreases",
      "threshold": "< 80%",
      "action": "FAIL activity",
      "reason": "New code is not properly tested"
    },
    {
      "condition": "new_critical_issues",
      "description": "New HIGH or CRITICAL Metabob issues introduced",
      "threshold": "> 0",
      "action": "FAIL activity",
      "reason": "Code quality degraded"
    },
    {
      "condition": "dead_code_added",
      "description": "Dead code or unused functions created",
      "threshold": "> 0 lines",
      "action": "FAIL activity",
      "reason": "Creates technical debt and confusion"
    },
    {
      "condition": "test_failures",
      "description": "Existing tests fail",
      "threshold": "> 0 failures",
      "action": "FAIL activity",
      "reason": "Regression or broken functionality"
    },
    {
      "condition": "fix_ineffective",
      "description": "Bug fix doesn't actually fix the bug",
      "test": "Reproducer test still fails",
      "action": "FAIL activity",
      "reason": "Fix was applied but doesn't work"
    }
  ],
  "soft_failures": [
    {
      "condition": "suboptimal_performance",
      "description": "Performance improvement less than target",
      "threshold": "< 20% improvement",
      "action": "WARN - allow manual override",
      "reason": "Fix works but not optimal"
    }
  ]
}
```

2. Create failure detection function:
```typescript
function checkActivityFailureConditions(activity: Activity): FailureReason[] {
  const failures: FailureReason[] = [];

  // Check for user input markers
  if (activity.output.includes('user') && activity.output.includes('input')) {
    failures.push({
      condition: 'requires_user_input',
      severity: 'CRITICAL',
      message: 'Activity requires manual user input - cannot be automated'
    });
  }

  // Check test coverage
  const coverage = activity.metrics.testCoverage;
  if (coverage < 0.80) {
    failures.push({
      condition: 'test_coverage_drop',
      severity: 'HIGH',
      message: `Test coverage ${(coverage * 100).toFixed(1)}% < 80%`
    });
  }

  // Check for new critical issues
  const newIssues = activity.metrics.newCriticalIssues;
  if (newIssues > 0) {
    failures.push({
      condition: 'new_critical_issues',
      severity: 'CRITICAL',
      message: `${newIssues} new critical Metabob issues`
    });
  }

  return failures;
}
```

3. Integrate into activity runner:
```typescript
// After activity completes
const failures = checkActivityFailureConditions(activity);
if (failures.some(f => f.severity === 'CRITICAL')) {
  console.error('ACTIVITY FAILED: Critical failure conditions detected');
  failures.forEach(f => console.error(`  - ${f.condition}: ${f.message}`));
  process.exit(1);
}
```
